/// @struct PrismConfig
/// @brief 播放器初始化配置
final class PrismConfig extends ffi.Struct {
  /// < 视频输出宽度（像素），0 表示使用原始分辨率
  @ffi.Int()
  external int video_output_width;

  /// < 视频输出高度（像素），0 表示使用原始分辨率
  @ffi.Int()
  external int video_output_height;

  /// < 音频采样率（Hz），0 表示使用原始采样率
  @ffi.Int()
  external int audio_sample_rate;

  /// < 默认音量，范围 0.0-1.0；config 为 NULL 时由 SDK 填 1.0
  @ffi.Float()
  external double default_volume;

  /// < 是否启用视频渲染；config 为 NULL 时由 SDK 填 true
  @ffi.Bool()
  external bool enable_video;

  /// < 是否启用音频输出；config 为 NULL 时由 SDK 填 true
  @ffi.Bool()
  external bool enable_audio;

  /// < spdlog 日志等级（"trace"/"debug"/"info"/"warn"/"error"），NULL 默认
  /// "info"
  external ffi.Pointer<ffi.Char> log_level;

  static ffi.Pointer<PrismConfig> $allocate(
    ffi.Allocator $allocator, {
    required int video_output_width,
    required int video_output_height,
    required int audio_sample_rate,
    required double default_volume,
    required bool enable_video,
    required bool enable_audio,
    required ffi.Pointer<ffi.Char> log_level,
  }) => $allocator<PrismConfig>()
    ..ref.video_output_width = video_output_width
    ..ref.video_output_height = video_output_height
    ..ref.audio_sample_rate = audio_sample_rate
    ..ref.default_volume = default_volume
    ..ref.enable_video = enable_video
    ..ref.enable_audio = enable_audio
    ..ref.log_level = log_level;
}

/// @enum PrismErrorCode
/// @brief 播放器操作错误码
enum PrismErrorCode {
  /// < 操作成功
  PRISM_OK(0),

  /// < 未知错误
  PRISM_ERROR_UNKNOWN(-1),

  /// < 无效的播放器句柄
  PRISM_ERROR_INVALID_HANDLE(-2),

  /// < 无效的参数
  PRISM_ERROR_INVALID_PARAM(-3),

  /// < 未加载媒体
  PRISM_ERROR_NO_MEDIA(-4),

  /// < 打开媒体失败
  PRISM_ERROR_OPEN_FAILED(-5),

  /// < Seek 操作失败
  PRISM_ERROR_SEEK_FAILED(-6),

  /// < 不支持的操作
  PRISM_ERROR_NOT_SUPPORTED(-7);

  final int value;
  const PrismErrorCode(this.value);

  static PrismErrorCode fromValue(int value) => switch (value) {
    0 => PRISM_OK,
    -1 => PRISM_ERROR_UNKNOWN,
    -2 => PRISM_ERROR_INVALID_HANDLE,
    -3 => PRISM_ERROR_INVALID_PARAM,
    -4 => PRISM_ERROR_NO_MEDIA,
    -5 => PRISM_ERROR_OPEN_FAILED,
    -6 => PRISM_ERROR_SEEK_FAILED,
    -7 => PRISM_ERROR_NOT_SUPPORTED,
    _ => throw ArgumentError('Unknown value for PrismErrorCode: $value'),
  };
}

/// @brief 播放器事件回调函数类型
/// @param type 事件类型，标识当前发生的事件
/// @param data 事件附加数据，各事件类型的携带数据不同（可为 NULL）
/// @param user_data set_event_callback 时透传的用户数据指针
typedef PrismEventCallback =
    ffi.Pointer<ffi.NativeFunction<PrismEventCallbackFunction>>;
typedef PrismEventCallbackFunction =
    ffi.Void Function(
      ffi.UnsignedInt type,
      ffi.Pointer<ffi.Void> data,
      ffi.Pointer<ffi.Void> user_data,
    );
typedef DartPrismEventCallbackFunction =
    void Function(
      PrismEventType type,
      ffi.Pointer<ffi.Void> data,
      ffi.Pointer<ffi.Void> user_data,
    );

/// @enum PrismEventType
/// @brief 播放器事件类型，通过回调通知上层
enum PrismEventType {
  /// < 媒体加载完成
  PRISM_EVENT_MEDIA_LOADED(0),

  /// < 播放完成
  PRISM_EVENT_PLAYBACK_COMPLETED(1),

  /// < Seek 操作完成
  PRISM_EVENT_SEEK_COMPLETED(2),

  /// < 缓冲开始
  PRISM_EVENT_BUFFERING_START(3),

  /// < 缓冲结束
  PRISM_EVENT_BUFFERING_END(4),

  /// < 发生错误
  PRISM_EVENT_ERROR(5),

  /// < 登录成功
  PRISM_EVENT_LOGIN_SUCCESS(6),

  /// < 登录失败
  PRISM_EVENT_LOGIN_FAILED(7),

  /// < 成功加入房间
  PRISM_EVENT_ROOM_JOINED(8),

  /// < 已离开房间
  PRISM_EVENT_ROOM_LEFT(9);

  final int value;
  const PrismEventType(this.value);

  static PrismEventType fromValue(int value) => switch (value) {
    0 => PRISM_EVENT_MEDIA_LOADED,
    1 => PRISM_EVENT_PLAYBACK_COMPLETED,
    2 => PRISM_EVENT_SEEK_COMPLETED,
    3 => PRISM_EVENT_BUFFERING_START,
    4 => PRISM_EVENT_BUFFERING_END,
    5 => PRISM_EVENT_ERROR,
    6 => PRISM_EVENT_LOGIN_SUCCESS,
    7 => PRISM_EVENT_LOGIN_FAILED,
    8 => PRISM_EVENT_ROOM_JOINED,
    9 => PRISM_EVENT_ROOM_LEFT,
    _ => throw ArgumentError('Unknown value for PrismEventType: $value'),
  };
}

