/// @enum PrismSeekMode
/// @brief Seek 跳转模式
enum PrismSeekMode {
  /// < 绝对跳转，position_ms 为目标位置
  PRISM_SEEK_ABSOLUTE(0),

  /// < 相对跳转，position_ms 为偏移量
  PRISM_SEEK_RELATIVE(1);

  final int value;
  const PrismSeekMode(this.value);

  static PrismSeekMode fromValue(int value) => switch (value) {
    0 => PRISM_SEEK_ABSOLUTE,
    1 => PRISM_SEEK_RELATIVE,
    _ => throw ArgumentError('Unknown value for PrismSeekMode: $value'),
  };
}

/// @enum PrismState
/// @brief 播放器播放状态
enum PrismState {
  /// < 空闲状态，未加载媒体
  PRISM_STATE_IDLE(0),

  /// < 媒体加载中
  PRISM_STATE_LOADING(1),

  /// < 播放中
  PRISM_STATE_PLAYING(2),

  /// < 已暂停
  PRISM_STATE_PAUSED(3),

  /// < 已停止
  PRISM_STATE_STOPPED(4),

  /// < 错误状态
  PRISM_STATE_ERROR(5);

  final int value;
  const PrismState(this.value);

  static PrismState fromValue(int value) => switch (value) {
    0 => PRISM_STATE_IDLE,
    1 => PRISM_STATE_LOADING,
    2 => PRISM_STATE_PLAYING,
    3 => PRISM_STATE_PAUSED,
    4 => PRISM_STATE_STOPPED,
    5 => PRISM_STATE_ERROR,
    _ => throw ArgumentError('Unknown value for PrismState: $value'),
  };
}

